import { applyPinCues, samePin } from './cues.ts';
import type { Cue, CueKind, DuelState, EffectKind, Timeline, Timing } from '../types/presenter.ts';

export function effectFor(scores: readonly number[]): EffectKind {
  const perfect = scores.filter(score => score === 5000).length;
  return perfect === 2 ? 'double-5k' : perfect === 1 ? 'single-5k' : 'none';
}

export const DEFAULT_TIMING: Timing = { leadMs: 200, countMs: 1200, damageMs: 800, effectWatchdogMs: 10000 };

function fresh(previous: Timeline | null, state: DuelState | null, nowMs: number): Timeline {
  const revision = (previous?.revision ?? 0) + 1;
  return {
    generation: `${state?.gameId ?? 'idle'}:${state?.round ?? 0}:${nowMs}:${revision}`,
    revision,
    gameId: state?.gameId ?? null,
    round: state?.round ?? null,
    phase: 'waiting-game',
    musicEpochMs: previous && previous.gameId === (state?.gameId ?? null) ? previous.musicEpochMs : nowMs,
    music: 'idle',
    effect: 'none',
    effectDeadlineMs: null,
    revealAtMs: null,
    damageAtMs: null,
    holdAtMs: null,
    cues: [],
    observed: {},
    countdownEndAtMs: null,
  };
}

function cue(timeline: Timeline, kind: CueKind, atMs: number, untilMs: number, playerId: string | null = null): Cue {
  return { id: `${timeline.generation}:${kind}:${playerId ?? 'all'}:${atMs}`, kind, atMs, untilMs, playerId };
}

function scheduleReveal(timeline: Timeline, atMs: number, timing: Timing): Timeline {
  const revealAtMs = atMs + timing.leadMs;
  const damageAtMs = revealAtMs + timing.countMs;
  const holdAtMs = damageAtMs + timing.damageMs;
  return {
    ...timeline,
    effect: 'none',
    effectDeadlineMs: null,
    revealAtMs,
    damageAtMs,
    holdAtMs,
    cues: [
      cue(timeline, 'results', revealAtMs, revealAtMs + 250),
      cue(timeline, 'count', revealAtMs, damageAtMs),
      ...(timeline.hasDamage === false ? [] : [cue(timeline, 'damage', damageAtMs, holdAtMs)]),
    ],
  };
}

/** Only the registered program graphic should be allowed to call this through NodeCG. */
export function finishEffect(timeline: Timeline, generation: string, nowMs: number, timing: Timing): Timeline {
  const effectStart = timeline.cues.find(item => item.kind === 'five-k')?.atMs;
  if (timeline.generation !== generation || timeline.effect === 'none'
    || timeline.phase !== 'results-transition' || effectStart === undefined || nowMs < effectStart) return timeline;
  // A late callback must use the same boundary as the watchdog tick.
  return scheduleReveal(timeline, Math.min(nowMs, timeline.effectDeadlineMs ?? nowMs), timing);
}

function liveCues(timeline: Timeline, state: DuelState, nowMs: number, bootstrap: boolean, timing: Timing): Timeline {
  const cues = timeline.cues.filter(item => item.untilMs > nowMs);
  const observed: Timeline['observed'] = {};
  const changedPins: Record<string, DuelState['players'][number]['pin']> = {};
  for (const player of state.players) {
    const old = timeline.observed[player.id];
    const guessed = player.guesses.some(guess => guess.round === timeline.round);
    if (!bootstrap && old && timeline.phase === 'live') {
      if (!samePin(player.pin, old.statePin)) changedPins[player.id] = player.pin;
      if (guessed && !old.guessed) cues.push({ id: `${state.gameId}/${state.round}/${player.id}/guess`, kind: 'guess',
        atMs: nowMs + timing.leadMs, untilMs: nowMs + timing.leadMs + 250, playerId: player.id });
    }
    observed[player.id] = { pin: bootstrap || !old ? player.pin : old.pin, statePin: player.pin, guessed, pinCueAtMs: old?.pinCueAtMs ?? null };
  }
  const round = state.rounds.find(item => item.number === timeline.round);
  const end = round?.endAtMs ?? null;
  const countdownEndAtMs = timeline.phase === 'live' || timeline.phase === 'pre-round' ? end : null;
  if (countdownEndAtMs !== timeline.countdownEndAtMs) {
    // First guess can replace the maximum-round deadline: remove its scheduled ticks.
    for (let i = cues.length - 1; i >= 0; i--) if (cues[i].kind === 'countdown') cues.splice(i, 1);
    if (countdownEndAtMs !== null) {
      for (let seconds = 3; seconds >= 1; seconds--) {
        const atMs = countdownEndAtMs - seconds * 1000;
        if (atMs >= nowMs + timing.leadMs && atMs >= (round?.startAtMs ?? 0)) {
          cues.push({ ...cue(timeline, 'countdown', atMs, atMs + 250), id: `${timeline.generation}:countdown:${countdownEndAtMs}:${seconds}` });
        }
      }
    }
  }
  return applyPinCues({ ...timeline, cues, observed, countdownEndAtMs }, changedPins, nowMs, timing);
}

/** Accept normalized authoritative state; call again on time boundaries even without a new snapshot. */
export function advanceTimeline(previous: Timeline | null, state: DuelState | null, nowMs: number, bootstrap: boolean, timing: Timing,
  effectWatchdogs: Partial<Record<Exclude<EffectKind, 'none'>, number>> = {}): Timeline {
  const replace = bootstrap || previous === null || previous.gameId !== (state?.gameId ?? null)
    || previous.round !== (state?.round ?? null) || (state?.aborted && previous.phase !== 'aborted');
  let timeline = replace ? fresh(previous, state, nowMs) : { ...previous! };
  if (state === null) return timeline;
  if (state.aborted) return { ...timeline, phase: 'aborted', music: 'idle' };

  const resolved = state.players.every(player => player.results.some(result => result.round === timeline.round));
  if (resolved) {
    if (bootstrap) {
      timeline = { ...timeline, revealAtMs: nowMs, damageAtMs: nowMs, holdAtMs: nowMs };
    } else if (timeline.revealAtMs === null && timeline.effect === 'none') {
      const scores = state.players.map(player => player.results.find(result => result.round === timeline.round)!.score);
      const effect = effectFor(scores);
      timeline = { ...timeline, phase: 'results-transition', music: 'results', cues: [], effect,
        hasDamage: state.players.some(player => player.results.some(result => result.round === timeline.round && result.healthAfter < result.healthBefore)) };
      if (effect === 'none') timeline = scheduleReveal(timeline, nowMs, timing);
      else {
        const startAtMs = nowMs + timing.leadMs;
        const watchdogMs = effectWatchdogs[effect] ?? timing.effectWatchdogMs;
        timeline = {
          ...timeline,
          effectDeadlineMs: startAtMs + watchdogMs,
          cues: [cue(timeline, 'five-k', startAtMs, startAtMs + watchdogMs)],
        };
      }
    }
    if (timeline.effectDeadlineMs !== null && nowMs >= timeline.effectDeadlineMs) {
      timeline = finishEffect(timeline, timeline.generation, timeline.effectDeadlineMs, timing);
    }
    const phase = timeline.holdAtMs !== null && nowMs >= timeline.holdAtMs
      ? state.status === 'Finished' ? 'finished' : state.manualRoundStart ? 'waiting-host' : 'between-rounds'
      : timeline.revealAtMs !== null && nowMs >= timeline.revealAtMs ? 'results-reveal' : 'results-transition';
    return { ...timeline, phase, music: phase === 'finished' ? 'idle' : 'results' };
  }

  const round = state.rounds.find(item => item.number === timeline.round);
  const phase = state.status === 'Finished' ? 'finished'
    : state.status === 'Created' || round?.startAtMs == null ? 'waiting-host'
    : nowMs < round.startAtMs ? 'pre-round' : 'live';
  const urgent = state.players.some(player => player.guesses.some(guess => guess.round === timeline.round))
    || (round?.endAtMs != null && round.endAtMs - nowMs <= 15000);
  timeline = {
    ...timeline,
    phase,
    music: phase === 'live' ? urgent ? 'urgent' : 'round' : phase === 'pre-round' ? 'round' : 'idle',
  };
  return liveCues(timeline, state, nowMs, bootstrap, timing);
}

/** Next coordinator wakeup. Browser sources schedule the individual timestamped cues themselves. */
export function nextTimelineWakeAtMs(timeline: Timeline, state: DuelState | null, nowMs: number): number | null {
  const boundaries = [timeline.effectDeadlineMs, timeline.revealAtMs, timeline.damageAtMs, timeline.holdAtMs];
  if (state?.gameId === timeline.gameId && (timeline.phase === 'pre-round' || timeline.phase === 'live')) {
    const round = state.rounds.find(item => item.number === timeline.round);
    boundaries.push(round?.startAtMs ?? null, round?.endAtMs == null ? null : round.endAtMs - 15000, round?.endAtMs ?? null);
  }
  const future = boundaries.filter((at): at is number => at !== null && at > nowMs);
  return future.length ? Math.min(...future) : null;
}

import type { DuelState, Projection, Timeline } from '../types/presenter.ts';

function progress(nowMs: number, startMs: number | null, endMs: number | null): number {
  if (startMs === null || endMs === null || nowMs < startMs) return 0;
  return endMs <= startMs ? 1 : Math.min(1, (nowMs - startMs) / (endMs - startMs));
}

export function project(state: DuelState | null, timeline: Timeline, nowMs: number): Projection {
  const empty: Projection = { phase: timeline.phase, remainingMs: null, answer: null, players: [] };
  if (state === null || state.gameId !== timeline.gameId) return empty;
  const round = state.rounds.find(item => item.number === timeline.round);
  const resolved = state.players.every(player => player.results.some(result => result.round === timeline.round));
  const revealed = resolved && timeline.phase !== 'aborted' && timeline.phase !== 'live'
    && timeline.phase !== 'pre-round' && timeline.revealAtMs !== null && nowMs >= timeline.revealAtMs;
  const scoreProgress = progress(nowMs, timeline.revealAtMs, timeline.damageAtMs);
  const damageProgress = progress(nowMs, timeline.damageAtMs, timeline.holdAtMs);
  const deadline = timeline.phase === 'pre-round' ? round?.startAtMs : timeline.phase === 'live' ? round?.endAtMs : null;
  return {
    phase: timeline.phase,
    remainingMs: deadline == null ? null : Math.max(0, deadline - nowMs),
    answer: revealed ? round?.panorama ?? null : null,
    players: state.players.map(player => {
      const result = player.results.find(item => item.round === timeline.round);
      return {
        id: player.id,
        health: result && timeline.phase !== 'aborted'
          ? Math.round(result.healthBefore + (result.healthAfter - result.healthBefore) * (revealed ? damageProgress : 0))
          : player.health,
        locked: player.guesses.some(guess => guess.round === timeline.round),
        score: revealed && result ? Math.round(result.score * scoreProgress) : null,
        distanceM: revealed ? result?.bestGuess?.distanceM ?? null : null,
      };
    }),
  };
}

import { REPLICANTS, type RendererStatus, type PresenterClients } from '../types/replicants.ts';
import type { DuelState, SeriesState, Timeline, Views } from '../types/presenter.ts';
import { DEFAULT_SETTINGS, type PresenterSettings } from '../presenter/settings.ts';
import { project } from '../presenter/projection.ts';
import { layoutKind, multiplierLabel, distanceLabel } from './presenter/layout.ts';
import { createGoogleRenderer } from './presenter/google.ts';
import type { GameRenderer, RenderFrame } from './presenter/renderer.ts';
import { clientRole, createPresenterClient } from './presenter/client.ts';
import { celebrationAsset, EMPTY_MEDIA, parseMedia, type AssetInventory, type MediaManifest } from '../presenter/media.ts';
import { createVideoPlayer } from './presenter/video.ts';
import { createAudioOutput } from './presenter/audio-output.ts';

const duel = nodecg.Replicant<DuelState | null>(REPLICANTS.presenterDuel);
const series = nodecg.Replicant<SeriesState>(REPLICANTS.presenterSeries);
const settings = nodecg.Replicant<PresenterSettings>(REPLICANTS.presenterSettings);
const timeline = nodecg.Replicant<Timeline>(REPLICANTS.presenterTimeline);
const views = nodecg.Replicant<Views | null>(REPLICANTS.presenterViews);
const clients = nodecg.Replicant<PresenterClients>(REPLICANTS.presenterClients);
const media = nodecg.Replicant<MediaManifest>(REPLICANTS.presenterMedia);
const videoAssets = nodecg.Replicant<AssetInventory>('assets:video');
let selectedMedia = EMPTY_MEDIA;
const videoPlayer = createVideoPlayer(() => {
  const video = document.createElement('video'); video.className = 'celebration-video'; document.body.append(video); return video;
}, (fn, ms) => { const id = setTimeout(fn, ms); return () => clearTimeout(id); });
media.on('change', value => {
  try { selectedMedia = parseMedia(value); } catch { selectedMedia = EMPTY_MEDIA; }
  videoPlayer.preload(selectedMedia);
  void audioOutput.load(selectedMedia);
});
const role = clientRole(location.search);
const clientId = crypto.randomUUID();
const client = createPresenterClient({ clientId, role, wallNow: () => Date.now(), monotonicNow: () => performance.now(),
  send: (name, body) => nodecg.sendMessage(name, body), schedule(fn, ms) { const id = setTimeout(fn, ms); return () => clearTimeout(id); } });
const audioOutput = createAudioOutput(client);
document.body.dataset.clientId = clientId; document.body.dataset.role = role;
function reconcileVideo() {
  const options = settings.value ?? DEFAULT_SETTINGS;
  videoPlayer.update(timeline.value?.generation ?? null, client.ownsProgram(), timeline.value?.effect ?? 'none', options.muted, options.effectsGain);
  audioOutput.sync(timeline.value, options);
}
clients.on('change', value => { if (value) client.updateClients(value); reconcileVideo(); });
timeline.on('change', value => { if (value) client.updateTimeline(value); reconcileVideo(); });
settings.on('change', reconcileVideo);
// Replicant events stop stale playback even when RAF is suspended. The timer
// also enforces local lease/clock expiry if the network drops while hidden.
const mediaGuard = setInterval(reconcileVideo, 250);
void client.start();
const element = (id: string) => document.getElementById(id)!;
const write = (id: string, value: string) => { const el = element(id); if (el.textContent !== value) el.textContent = value; };
let renderer: GameRenderer | null = null;
let previousFrame: RenderFrame | null = null;
function publishRenderer(status: RendererStatus) {
  document.body.dataset.renderer = status;
  client.setRendererStatus(status); client.setReady(status === 'api-ready');
}
function rendererError(message: string) {
  publishRenderer(message === 'Google Maps browser key missing' ? 'missing-key' : message === 'Exact Street View panorama unavailable' ? 'pano-error'
    : message === 'Google Maps view unavailable' ? 'view-error' : 'api-error');
  const placeholder = element('results-map').querySelector('span');
  if (placeholder) placeholder.textContent = 'Map unavailable';
}
const publicConfig = nodecg.bundleConfig as { presenter?: { googleMapsApiKey?: unknown } };
const apiKey = publicConfig.presenter?.googleMapsApiKey;
publishRenderer('loading');
void createGoogleRenderer(document.body, typeof apiKey === 'string' ? apiKey : '', rendererError, () => publishRenderer('api-ready'))
  .then(value => { renderer = value; publishRenderer('api-ready'); }).catch(() => {});
window.addEventListener('pagehide', () => { clearInterval(mediaGuard); videoPlayer.dispose(); audioOutput.dispose(); client.dispose(); renderer?.dispose(); });

function frame() {
  document.body.dataset.program = String(client.ownsProgram());
  const state = duel.value;
  const timing = timeline.value;
  const match = series.value;
  const options = settings.value ?? DEFAULT_SETTINGS;
  // Sole graphic cue consumer; sound scheduling belongs to the audio lease engine.
  for (const cue of client.pollCues()) if (cue.kind === 'five-k' && timing) {
    const complete = client.effectCompletion(timing);
    const asset = celebrationAsset(selectedMedia, timing.effect, videoAssets.value ?? []);
    if (asset) videoPlayer.play(asset, timing.generation, (_generation, failed) => { void complete(failed); }, options.muted, options.effectsGain);
    else void complete(true);
  }
  reconcileVideo();
  document.documentElement.style.setProperty('--key-color', options.keyColor);
  document.body.dataset.source = options.viewSource;
  document.body.dataset.layout = layoutKind(state?.mode ?? 'NMPZ', options.viewSource);
  if (timing && match) {
    const visible = project(state ?? null, timing, client.now());
    document.body.dataset.phase = visible.phase;
    const results = visible.answer !== null;
    element('results-area').hidden = !results;
    element('live-area').hidden = results || visible.phase === 'results-transition';
    element('transition').hidden = visible.phase !== 'results-transition';
    write('round-number', timing.round === null ? '—' : String(timing.round));
    write('mode', state?.mode ?? '—');
    const multiplier = multiplierLabel(state ?? null, timing, { left: match.left.playerId, right: match.right.playerId });
    write('multiplier', multiplier.replace(' · ', '\n'));
    element('multiplier').classList.toggle('split', multiplier.startsWith('L '));
    for (const side of ['left', 'right'] as const) {
      const competitor = match[side];
      const player = visible.players.find(item => item.id === competitor.playerId);
      write(`${side}-name`, competitor.name);
      write(`${side}-handle`, competitor.handle);
      write(`${side}-wins`, String(competitor.wins));
      write(`${side}-health`, player ? String(player.health) : '—');
      const health = Math.max(0, Math.min(1, (player?.health ?? 0) / (state?.initialHealth || 6000)));
      element(`${side}-health-fill`).style.transform = `scaleX(${health})`;
      element(`${side}-health-fill`).style.background = health < 0.25 ? '#e04f66' : health < 0.5 ? '#dbae40' : '#8abb43';
      element(`${side}-lock`).hidden = visible.phase !== 'live' || !player?.locked;
      write(`${side}-score`, player?.score == null ? '—' : String(player.score));
      const distance = player?.distanceM;
      write(`${side}-distance`, distanceLabel(distance, player?.score));
    }
    element('timer').hidden = visible.remainingMs === null;
    element('timer').classList.toggle('urgent', timing.music === 'urgent');
    const seconds = Math.ceil((visible.remainingMs ?? 0) / 1000);
    write('timer', `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`);
    const labels = { 'waiting-game': 'WAITING FOR GAME', 'waiting-host': 'WAITING FOR NEXT ROUND', 'pre-round': 'ROUND STARTING', live: '', 'results-transition': 'ROUND COMPLETE', 'results-reveal': 'ROUND RESULTS', 'between-rounds': 'NEXT ROUND', finished: 'GAME FINISHED', aborted: 'GAME ABORTED' };
    let label = labels[visible.phase];
    if (visible.phase === 'finished' && state) {
      if (state.isDraw) label = 'DRAW';
      else {
        const winner = state.players.find(player => player.teamId === state.winnerTeamId);
        const competitor = [match.left, match.right].find(item => item.playerId === winner?.id);
        if (competitor) label = `${competitor.name} WINS`;
      }
    }
    write('phase-label', label);
    if (state && views.value) {
      previousFrame = { state, views: views.value, projection: visible, source: options.viewSource,
        displayedRound: timing.round, playerIds: { left: match.left.playerId, right: match.right.playerId } };
      renderer?.render(previousFrame);
    }
  }
  if ((!state || !views.value || !timing || !match) && previousFrame) {
    renderer?.render({ ...previousFrame, source: options.viewSource, projection: { phase: 'waiting-game', answer: null, players: [], remainingMs: null } });
    previousFrame = null;
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

