.player-window { position: absolute; top: 270px; width: 910px; height: 512px; border: 4px solid var(--blue); border-radius: 10px; overflow: hidden; box-shadow: 0 8px 25px #0007; }.player-window.left { left: 40px; }.player-window.right { right: 40px; border-color: var(--red); }
