body[data-layout="shared"] .shared-view { display: grid; }body[data-layout="shared"] .player-view { display: none; }body[data-layout="shared"] .player-window { border-color: transparent; box-shadow: none; pointer-events: none; }
.lock { position: absolute; left: 50%; top: 45%; transform: translate(-50%, -50%); border: 2px solid #ffffffb0; background: #182b51; padding: 13px 28px; border-radius: 5px; font-size: 33px; font-weight: 800; white-space: nowrap; box-shadow: 0 5px 25px #0006; z-index: 2; }.right .lock { background: #532331; }
